cd /tmp/sv-1e40563213d747beab609864d858e174/simple-single-project/MyApp && dotnet list package --format json > ../after-cpm-packages.json 2>&1 && python3 -c "
import json
with open('../baseline-packages.json') as f: baseline = json.load(f)
with open('../after-cpm-packages.json') as f: after = json.load(f)
def get_pkgs(data):
    pkgs = {}
    for proj in data.get('projects', []):
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = pkg['resolvedVersion']
    return pkgs
b, a = get_pkgs(baseline), get_pkgs(after)
if b == a: print('All package versions match baseline.')
else: print('DIFFERENCES:', {k: (b.get(k), a.get(k)) for k in set(list(b)+list(a)) if b.get(k) != a.get(k)})
"

